    pub flush_now: bool,
    pub events_json: String,
    pub camera: Option<[f64; 3]>,
}

impl CoalescedBoardEvents {
    /// 📬️ Whether any board row remains for `applyBoardEvents`.
    pub fn has_rows(&self) -> bool {
        self.events_json != "[]"
    }
}

